import json,pathlib,hashlib,re,collections
from math_helpers import parse,target,field,correct,sp,x
P=pathlib.Path(__file__).resolve().parent;J=P.parent;PKG=J/'workspace'
load=lambda n:json.loads((P/n).read_text())
def save(n,v):(P/n).write_text(json.dumps(v,indent=2))
v=load('variation-results.json');probes=[]
for z in v['position_probes']:
 if not z['total']:continue
 probes.append({'cue':'answer position','subgroup':z['stage']+'/'+z['profile'],'scope':'overall' if z['profile']=='all' else 'within_template','strategy':z['strategy'],'correct':z['correct'],'total':z['total'],'baseline':.2,'disposition':'not_predictive','conclusion':'Five radio alternatives give uniform guessing baseline 0.2. No tested first-position rule answers the batch or repeated family; single-item subgroups cannot establish or refute a systematic cue. Serialized order is not displayed order.','sample_refs':['variation-results.json','render-records.json']})
sets={'raw sample':load('samples.json'),'delivered sample':load('delivery-samples/accepted.json'),'actual batch':load('batch.json'),'delivered batch':load('delivery-batch/accepted.json')}
for name,rs in sets.items():
 rr=[r for r in rs if r['generation']['bank_profile']=='quotient']
 for strategy in ['always positive unit reciprocal','preserve signed reciprocal constant']:
  good=0
  for r in rr:
   # Derive denominator and sign from the visible function, never generation metadata.
   c=sp.simplify(target(r)*x);prediction=abs(c)/x if strategy.startswith('always') else c/x
   good+=int(sp.simplify(prediction-target(r))==0)
  probes.append({'cue':'quotient presentation','subgroup':name+'/quotient','scope':'within_template','strategy':strategy,'correct':good,'total':len(rr),'baseline':.2,'disposition':'not_predictive' if strategy.startswith('always') else 'intended_skill','conclusion':'Random choice among five is 0.2. Ignoring sign fails on negative quotients. Reading the signed constant 1/d and replacing ln(x) by 1/x performs exactly the sourced differentiation; its perfect success is instructional, not incidental.','sample_refs':['samples.json','batch.json','delivery-samples/accepted.json','delivery-batch/accepted.json']})
# Capture actual delivered UI order separately from raw serialization.
delivered=load('delivery-batch/accepted.json');ui=[]
for i,r in enumerate(delivered):
 if not field(r)[':answer-field/type'].endswith('/radio'):continue
 ids=re.findall(r'<input type="radio"[^>]* value="([^"]+)"',(P/'render-delivered'/f'question-{i+1:03}.html').read_text())
 assert len(ids)==5
 ui.append({'question_id':r['question'][':question/id'],'profile':r['generation']['bank_profile'],'displayed_answer_ids':ids,'position':ids.index(field(r)[':answer-field/correct'][1])})
save('delivered-ui-positions.json',ui)
for profile in ['all','quotient','fraction']:
 rr=[r for r in ui if profile=='all' or r['profile']==profile]
 probes.append({'cue':'displayed position','subgroup':'delivered actual batch/'+profile,'scope':'overall' if profile=='all' else 'within_template','strategy':'choose first displayed answer','correct':sum(z['position']==0 for z in rr),'total':len(rr),'baseline':.2,'disposition':'not_predictive','conclusion':'Baseline is uniform 1/5 radio guessing. This records the actual UI shuffle; a singleton subgroup does not demonstrate a recurring shortcut.','sample_refs':['delivered-ui-positions.json','delivery-batch/accepted.json']})
cf=[]
for z in v['counterfactuals']:
 for kind in ['relevant','irrelevant']:
  required=['relevant_prompt_changed','relevant_solution_changed','relevant_key_changed'] if kind=='relevant' else ['irrelevant_prompt_preserved','irrelevant_solution_preserved','irrelevant_key_preserved']
  assert all(z[k] for k in required)
  cf.append({'kind':kind,'change':z['profile']+(': change coefficient or sign at fixed seed' if kind=='relevant' else ': change shuffle seed with coefficient fixed'),'expected':'Prompt, every coefficient-dependent solution step and correct derivative change' if kind=='relevant' else 'Derivative and solution are preserved despite harmless choice-order variation','observed':str({k:z[k] for k in required})+'; all choice responses and blank equivalents checked by native grader; UI renders all three records.','status':'passed','justification':'The source constant-multiple rule depends on the coefficient, not choice order or random seed. A one-answer blank has no meaningful choice-order change.','sample_refs':['counterfactuals.json','grader-report.json','render-pairs/rendering.json','variation-results.json']})
cf.append({'kind':'relevant','change':'Hold positive quotient form fixed; denominator 4 -> 5','expected':'1/(4x) -> 1/(5x), including rewriting row and final key','observed':'Visible prompts, solution rows, native radio acceptance/rejection and inspected rendered pair follow the new denominator.','status':'passed','justification':'q-70887 requires identifying the denominator as part of the constant.','sample_refs':['denominator-counterfactual.json','solution-rows.json','grader-report.json','render-records.json']})
ped={'learner_operation':'Identify the entire signed constant multiplying ln(x), rewrite ln(x)/d as (1/d)ln(x), and apply the constant-multiple rule to produce c/x.','fixed_features':[{'feature':'Single ln(x), x>0, derivative with respect to x','justification':'Tutorial and canonical example teach this derivative; changing arguments or adding terms introduces other knowledge points.'},{'feature':'One correct answer in a five-option radio bank or an equivalent-expression blank','justification':'Captured response contracts. The count constrains the response format, not which option qualifies.'},{'feature':'Modest reduced nonzero constants and distinct choices','justification':'Preserves easy workload. Denominator 1 collapses quotient distractors; numerator 1 collides in the original fraction bank but is now reachable in quotient and blank families.'}],'answer_roles':[{'role':'coefficient sign and magnitude','eligible_variation':'Signed integers, fractions, unit fractions and multiples of e','observed':'Six profiles present; both quotient signs and distinct denominators survive delivery.'},{'role':'quotient denominator','eligible_variation':'Small denominators with a valid five-option bank','observed':'Independent boundaries 2,4,12 and controlled 4->5; author regression independently rerun across all 2..12 with both signs.'},{'role':'correct option position','eligible_variation':'Any option position; irrelevant to differentiation','observed':'Varied serialized and actual UI positions, separately measured.'}],'coverage':[{'case':name,'sample_refs':['variation-results.json','batch.json' if 'batch' in name else 'samples.json'],'result':json.dumps(c)} for name,c in v['coverage'].items()],'counterfactuals':cf,'shortcut_probes':probes,'delivery':{'stages_examined':['parameter rejection and finite-domain sampling','CLI deterministic seed sequence','requested difficulty','actual publisher normalization and deduplication','captured inventory eligibility and retirement','learner freshness exclusion and difficulty-first selection rules','actual UI option shuffle'],'sample_refs':['rejections.json','packaging.json','delivery-batch/delivery.json','delivery-samples/delivery.json','selection-results.json','inventory-results.json','delivered-ui-positions.json'],'result':'5/5 actual batch records and 38/43 independent samples survive. All six sampled profiles survive. Batch has five distinct derivatives and three quotient records with both signs and denominators 5,8,9; no tested cue answers all of it. Captured pool has nine keyed, nonretired ordinary records. Positive easy weight selects uniformly within the fresh easy band; unconfigured policy chooses lowest ID. No live draws claimed.'},'limitations':['Captured inventory basis 5668; concurrent writes may alter deduplication.','No live learner history, policy weights or future database entity IDs supplied; selection rules and explicit modeled histories were examined read-only.','Singleton batch subgroups cannot support statistical shortcut claims; finite tests cannot exclude every heuristic.','Requested easy difficulty only.']}
save('pedagogical-variation.json',ped)
save('sampling-analysis.json',{'source_of_conclusions':'Inspected validate_parameters, bank_values, parameter_domain, generate and main in current entrypoint; independent records in samples.json','rejection':'Finite domain enumerates exact reduced coefficients and rejects invalid or colliding banks before uniform choice. No retry-driven family starvation; template chosen before bank and parameters.','quotient_domain':'n = +/-1, d=2..12, k=0: 22 signed unit-fraction decisions. Sign and denominator are independent; five expressions are distinct for each.','template_sampling':'Four easy templates sampled uniformly; legacy-radio has integer/fraction, radio-dot integer/euler, blank canonical/equivalent-entry, quotient-radio quotient. Six profiles observed fresh and after delivery.','batch_rule':'CLI uses consecutive seeds 3129290382..3129290386. Exact five-record replay and relocation match runner batch. No systematic tested batch cue found.','boundaries':'Accepted unit-fraction normal practice; rejects zero, unreduced 2/2, numerator 31, denominator 13 and unsupported easy Euler exponent. Source-bank collisions justify profile-specific exclusions, not global unit-fraction exclusion.','external_output':'No generated assets or external output paths; package only reads its two source JSON dependencies.'})
# Capture no-change proof for the entire supplied package, including nonmanifest files.
after={str(q.relative_to(PKG)):hashlib.sha256(q.read_bytes()).hexdigest() for q in PKG.rglob('*') if q.is_file()};save('package-after.json',after);assert after==load('package-before.json')
assert load('packaging.json')['actual_versions']=={'python':'3.13.5','sympy':'1.14.0'}
assert load('packaging.json')['manifest_dependencies']=={'python':'3.13.5','packages':{'sympy':'1.14.0'}}
save('render-inspection.json',{'passed':True,'actual_ui_records':25,'delivered_records':5,'screenshots_inspected':['render-delivered/question-001.png','render-delivered/question-003.png','render-pairs/question-006.png','render-pairs/question-007.png','render-pairs/question-025.png'],'observations':'Clear quotient signs and denominators; complete five-stage rewrite; 4->5 and positive->negative changes visible. Blank controls, radio controls and all worked notation display correctly. No clipping or MathJax errors observed.'})
